(function () {
var self = document.currentScript;
var gtm = self && self.dataset.gtmId;
var KEY = 'pl_consent';
window.dataLayer = window.dataLayer || [];
function gtag() { window.dataLayer.push(arguments); }
window.__plConsent = null;
if (!gtm) return;
function read() { try { return localStorage.getItem(KEY); } catch (e) { return null; } }
function write(v) { try { localStorage.setItem(KEY, v); } catch (e) {} }
function clearCookies() {
document.cookie.split(';').forEach(function (c) {
var n = c.split('=')[0].trim();
if (n === '_ga' || n.indexOf('_ga_') === 0 || n === '_gid' || n.indexOf('_gat') === 0) {
[location.hostname, '.' + location.hostname.replace(/^www\./, ''), ''].forEach(function (d) {
document.cookie = n + '=; expires=Thu, 01 Jan 1970 00:00:00 GMT; path=/' + (d ? '; domain=' + d : '');
});
}
});
}
gtag('consent', 'default', { analytics_storage: 'denied', ad_storage: 'denied', ad_user_data: 'denied', ad_personalization: 'denied' });
var loaded = false;
function load() {
if (loaded) return;
loaded = true;
gtag('consent', 'update', { analytics_storage: 'granted' });
window.dataLayer.push({ 'gtm.start': Date.now(), event: 'gtm.js' });
var s = document.createElement('script');
s.async = true;
s.src = 'https://www.googletagmanager.com/gtm.js?id=' + encodeURIComponent(gtm);
document.head.appendChild(s);
}
document.addEventListener('DOMContentLoaded', function () {
var box = document.getElementById('consent');
var openBtn = document.getElementById('consent-open');
if (!box) return;
var last = null;
function show(from) { last = from || null; box.hidden = false; if (from) { var b = box.querySelector('[data-consent]'); if (b) b.focus(); } }
function hide() { box.hidden = true; if (last) { last.focus(); last = null; } }
function choose(v) {
var prev = read();
write(v);
window.__plConsent = v;
if (v === 'granted') { load(); hide(); }
else { clearCookies(); hide(); if (prev === 'granted') location.reload(); }
}
box.addEventListener('click', function (e) { var b = e.target.closest('[data-consent]'); if (b) choose(b.dataset.consent); });
box.addEventListener('keydown', function (e) { if (e.key === 'Escape') hide(); });
if (openBtn) openBtn.addEventListener('click', function () { show(openBtn); });
var cur = read();
window.__plConsent = cur;
if (cur === 'granted') load(); else if (cur !== 'denied') show();
});
})();
(function () {
window.dataLayer = window.dataLayer || [];
function gtag() { window.dataLayer.push(arguments); }
var self = document.currentScript;
var id = self && self.dataset.ga4Id;
if (id) {
var s = document.createElement('script');
s.async = true;
s.src = 'https://www.googletagmanager.com/gtag/js?id=' + encodeURIComponent(id);
document.head.appendChild(s);
gtag('js', new Date());
gtag('config', id, { anonymize_ip: true });
}
function snake(k) { return k.replace(/[A-Z]/g, function (c) { return '_' + c.toLowerCase(); }); }
document.addEventListener('click', function (ev) {
var el = ev.target.closest('[data-event]');
if (!el) return;
if (window.__plConsent !== 'granted') return; // sem consentimento, nada é registrado
var params = { page_path: location.pathname };
Object.keys(el.dataset).forEach(function (k) {
if (k === 'event' || k.indexOf('email') === 0) return; // nunca envia o e-mail
params[snake(k)] = el.dataset[k];
});
window.dataLayer.push({ event: el.dataset.event, params: params });
if (id) gtag('event', el.dataset.event, params);
}, true);
})();
(function () {
var toggle = document.querySelector('.nav-toggle');
var nav = document.getElementById('nav');
if (!toggle || !nav) return;
function setOpen(open) {
nav.classList.toggle('is-open', open);
toggle.setAttribute('aria-expanded', String(open));
toggle.setAttribute('aria-label', open ? 'Fechar menu' : 'Abrir menu');
toggle.querySelector('use').setAttribute('href', open ? '#i-x' : '#i-menu');
}
toggle.addEventListener('click', function () { setOpen(!nav.classList.contains('is-open')); });
nav.addEventListener('click', function (e) { if (e.target.closest('a')) setOpen(false); });
document.addEventListener('keydown', function (e) {
if (e.key === 'Escape' && nav.classList.contains('is-open')) { setOpen(false); toggle.focus(); }
});
})();
(function () {
document.querySelectorAll('[data-email-user]').forEach(function (a) {
var addr = a.dataset.emailUser + '@' + a.dataset.emailDomain;
a.href = 'mailto:' + addr;
var meta = a.closest('.social') && a.closest('.social').querySelector('[data-email-text]');
if (meta) meta.textContent = addr;
});
})();
(function () {
var bar = document.querySelector('.filter');
if (!bar) return;
bar.hidden = false;
var cards = document.querySelectorAll('[data-path]');
var sections = document.querySelectorAll('[data-filter-section]');
var empty = document.getElementById('filter-empty');
bar.addEventListener('click', function (e) {
var b = e.target.closest('[data-filter]');
if (!b) return;
var f = b.dataset.filter;
bar.querySelectorAll('[data-filter]').forEach(function (x) { x.setAttribute('aria-pressed', String(x === b)); });
var shown = 0;
cards.forEach(function (c) { var ok = f === 'todos' || c.dataset.path === f; c.hidden = !ok; if (ok) shown++; });
sections.forEach(function (s) { s.hidden = !s.querySelector('[data-path]:not([hidden])'); });
if (empty) empty.hidden = shown !== 0;
});
})();
